export interface ConnectorConfig {
  airtableBaseId: string
  airtableTableName: string
  airtablePat: string
  fetch?: typeof fetch
}

export interface ShopifyOrderPaidPayload {
  order_id: string
  customer: {
    email: string
  }
  total_price: string
}

export interface AirtableCreateRecordResponse {
  id: string
  fields: {
    'Order ID': string
    'Customer Email': string
    Total: number
  }
  createdTime: string
}

export interface HandleResult {
  recordId: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function validatePayload(payload: unknown): asserts payload is ShopifyOrderPaidPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (typeof p.order_id !== 'string' || p.order_id === '') {
    throw new Error('Missing required field: order_id')
  }
  if (!p.customer || typeof p.customer !== 'object') {
    throw new Error('Missing required field: customer')
  }
  const customer = p.customer as Record<string, unknown>
  if (typeof customer.email !== 'string' || customer.email === '') {
    throw new Error('Missing required field: customer.email')
  }
  if (typeof p.total_price !== 'string' || p.total_price === '') {
    throw new Error('Missing required field: total_price')
  }
}

export async function handle(
  payload: ShopifyOrderPaidPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)

  const total = Number(payload.total_price)
  if (Number.isNaN(total)) {
    throw new Error(`total_price "${payload.total_price}" is not a valid number`)
  }

  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableName}`
  const body = {
    fields: {
      'Order ID': payload.order_id,
      'Customer Email': payload.customer.email,
      Total: total,
    },
  }

  const fetchFn = getFetch(config)
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.airtablePat}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`Airtable create record failed: ${response.status} ${response.statusText} at ${url}`)
  }

  const data = (await response.json()) as AirtableCreateRecordResponse
  return { recordId: data.id }
}

